   "desc": "Fundamental concepts, paradigms, and structures of programming languages. Syntax and semantics, language design principles, and programming paradigms, including imperative, functional, and object-oriented programming. Syntax and semantics, type systems, memory management, and abstraction mechanisms. In-depth examination of OOP principles, including encapsulation, inheritance, polymorphism, and advanced design techniques.",
   "th_learn": "เปรียบเทียบภาษาโปรแกรมและแนวคิดการเขียนโปรแกรม รวมถึงการเขียนโปรแกรมเชิงวัตถุ",
