    "เลือกกระบวนทัศน์การเขียนโปรแกรมที่เหมาะสมในการแก้ปัญหาแบบต่างๆ",
    "ออกแบบการห่อหุ้ม การสืบ ทอด และพหุนิยม (Polymorphism) ในการโปรแกรมเชิงอ๊อบเจกต์"
