   "th_desc": "แนวคิดพื้นฐานของความปลอดภัยทางไซเบอร์, การเข้ารหัสข้อมูล, ความปลอดภัยของเครือข่าย และความปลอดภัย ของเว็บ. การเข้า รหัส แบบสมมาตรและอสมมาตร, การพิสูจน์ตัวตนและการกำหนดสิทธิ์, ภัยคุกคามในเครือข่าย, การควบคุมความปลอดภัยของเครือข่าย, ไฟร์วอลล์, ระบบตรวจจับการบุกรุก. การโจมตีแบบ SQL Injection, การจี้เซสชัน (Session Hi-jacking), การโจมตี Cross- site scripting. การโจมตีแ บบ Distributed Denial-of-Service (DDoS), การโจมตีแบบบัฟเฟอร์ล้น (Buffer Overflow). การเขียนโค้ดอย่างปลอดภัย, การตรวจสอบและบันทึกข้อมูล (Monitoring and Logging).",
